mapper.select:
SELECT GROUP_ID ,GROUP_NAME ,USE_FLAG ,GROUP_MARKET ,COUNT(TSIW.STOCK_CODE) AS STOCK_COUNT ,GROUP_SEQ ,TSIG.CREATE_DATE AS CREATE_DATE FROM TB_S_INTEREST_GROUP TSIG LEFT JOIN TB_S_INTEREST_WATCHLIST TSIW ON TSIG.GROUP_ID = TSIW.STOCK_GROUP WHERE 1=1 AND USE_FLAG ='Y'
AND GROUP_MARKET = #{market}
GROUP BY GROUP_ID, GROUP_NAME, USE_FLAG, GROUP_MARKET, GROUP_SEQ, TSIG.CREATE_DATE ORDER BY CREATE_DATE DESC

SELECT W.STOCK_SEQ, W.STOCK_CODE, W.STOCK_GROUP, CASE WHEN W.STOCK_GROUP_DIV IS NULL OR TRIM(W.STOCK_GROUP_DIV) = '' THEN 'normal' WHEN LOWER(TRIM(W.STOCK_GROUP_DIV)) IN ('close', 'undefined') THEN 'normal' WHEN LOWER(TRIM(W.STOCK_GROUP_DIV)) = 'monthend' THEN 'month' ELSE LOWER(TRIM(W.STOCK_GROUP_DIV)) END AS STOCK_GROUP_DIV, W.STOCK_CLOSE, S.STOCK_KO_NAME, S.STOCK_EN_NAME, S.STOCK_MARKET, S.STOCK_COUNTRY_CODE, A.STOCK_MACD_SIGNAL AS RECO_SIGNAL_CODE, NVL(( SELECT /*+ FULL(E1) NO_INDEX(E1 IX_TB_S_SIGNAL_EVENT_01) */ MAX(E1.MESSAGE) KEEP (DENSE_RANK LAST ORDER BY E1.EVENT_TIME, E1.EVENT_ID) FROM TB_S_SIGNAL_EVENT E1 WHERE E1.STOCK_CODE = W.STOCK_CODE ), ('일봉 MACD:'||NVL(A.STOCK_MACD_SIGNAL,'-') ||' / 월봉:'||NVL(A.STOCK_MON,'-') ||' / 정배열:'||NVL(A.STOCK_SMA_LINES,'-')) ) AS RECO_EVENT_SUMMARY FROM TB_S_INTEREST_WATCHLIST W LEFT JOIN TB_S_INTEREST_STOCK S ON W.STOCK_CODE = S.STOCK_CODE LEFT JOIN TB_S_STOCK_ANALYSIS A ON W.STOCK_CODE = A.STOCK_CODE WHERE 1=1
AND W.STOCK_GROUP = #{groupId}
AND ( (#{market} = 'N' AND S.STOCK_COUNTRY_CODE = 'KR') OR (#{market} = 'A' AND S.STOCK_COUNTRY_CODE != 'KR') OR W.STOCK_GROUP_DIV = #{market} )
AND ( CASE WHEN W.STOCK_GROUP_DIV IS NULL OR TRIM(W.STOCK_GROUP_DIV) = '' THEN 'normal' WHEN LOWER(TRIM(W.STOCK_GROUP_DIV)) IN ('close', 'undefined') THEN 'normal' WHEN LOWER(TRIM(W.STOCK_GROUP_DIV)) = 'monthend' THEN 'month' ELSE LOWER(TRIM(W.STOCK_GROUP_DIV)) END ) = #{groupDiv}
ORDER BY W.STOCK_SEQ ASC
